-- Nueva base de datos; no modifica tablas heredadas. Ejecutar en Supabase SQL Editor.
-- Todos los importes se almacenan en céntimos para evitar errores de coma flotante.
create table if not exists public.households (
  id uuid primary key default gen_random_uuid(), name text not null check (char_length(name) between 1 and 80),
  split_method text not null default 'equal' check (split_method in ('equal','income_proportional')),
  invite_code text not null unique default upper(substr(md5(random()::text || clock_timestamp()::text),1,8)), created_at timestamptz not null default now()
);
create table if not exists public.household_members (
  household_id uuid not null references public.households(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade,
  joined_at timestamptz not null default now(), primary key (household_id,user_id)
);
create table if not exists public.categories (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, name text not null, kind text not null check(kind in('income','expense')), color text not null default '#0a5c59', archived_at timestamptz, unique(household_id,name,kind));
create table if not exists public.transactions (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, user_id uuid not null references auth.users(id), kind text not null check(kind in('income','expense')), scope text not null check(scope in('shared','personal')), category_id uuid references public.categories(id), amount_cents bigint not null check(amount_cents>0), occurred_on date not null, note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table if not exists public.recurring_transactions (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, created_by uuid not null references auth.users(id), kind text not null check(kind in('income','expense')), scope text not null check(scope in('shared','personal')), category_id uuid references public.categories(id), amount_cents bigint not null check(amount_cents>0), day_of_month int not null check(day_of_month between 1 and 31), starts_on date not null, ends_on date, note text, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.budgets (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, category_id uuid not null references public.categories(id), month date not null check(month=date_trunc('month',month)::date), limit_cents bigint not null check(limit_cents>=0), unique(household_id,category_id,month));
create table if not exists public.goals (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, name text not null, target_cents bigint not null check(target_cents>0), saved_cents bigint not null default 0 check(saved_cents>=0), target_date date, archived_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.debts (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, name text not null, amount_cents bigint not null check(amount_cents>0), paid_cents bigint not null default 0 check(paid_cents between 0 and amount_cents), due_on date not null, scope text not null check(scope in('shared','personal')), created_at timestamptz not null default now(), archived_at timestamptz);

create or replace function public.is_household_member(target_household uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.household_members where household_id=target_household and user_id=auth.uid()) $$;
create or replace function public.create_household(household_name text, method text default 'equal') returns public.households language plpgsql security definer set search_path=public as $$ declare result public.households; begin if auth.uid() is null then raise exception 'authentication required'; end if method not in ('equal','income_proportional') then raise exception 'invalid split method'; end if; insert into public.households(name,split_method) values (household_name,method) returning * into result; insert into public.household_members(household_id,user_id) values(result.id,auth.uid()); return result; end $$;
create or replace function public.join_household(code text) returns uuid language plpgsql security definer set search_path=public as $$ declare target uuid; begin if auth.uid() is null then raise exception 'authentication required'; end if; select id into target from public.households where invite_code=upper(trim(code)); if target is null then raise exception 'invalid invitation code'; end if; insert into public.household_members(household_id,user_id) values(target,auth.uid()) on conflict do nothing; return target; end $$;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
drop trigger if exists transactions_set_updated_at on public.transactions; create trigger transactions_set_updated_at before update on public.transactions for each row execute function public.set_updated_at();

alter table public.households enable row level security; alter table public.household_members enable row level security; alter table public.categories enable row level security; alter table public.transactions enable row level security; alter table public.recurring_transactions enable row level security; alter table public.budgets enable row level security; alter table public.goals enable row level security; alter table public.debts enable row level security;
drop policy if exists "members read households" on public.households; drop policy if exists "members read membership" on public.household_members; drop policy if exists "members read categories" on public.categories; drop policy if exists "members write categories" on public.categories; drop policy if exists "members read transactions" on public.transactions; drop policy if exists "members insert own transactions" on public.transactions; drop policy if exists "owners update transactions" on public.transactions; drop policy if exists "members manage recurring" on public.recurring_transactions; drop policy if exists "members manage budgets" on public.budgets; drop policy if exists "members manage goals" on public.goals; drop policy if exists "members manage debts" on public.debts;
create policy "members read households" on public.households for select using(public.is_household_member(id));
create policy "members read membership" on public.household_members for select using(public.is_household_member(household_id));
create policy "members read categories" on public.categories for select using(public.is_household_member(household_id)); create policy "members write categories" on public.categories for all using(public.is_household_member(household_id)) with check(public.is_household_member(household_id));
create policy "members read transactions" on public.transactions for select using(public.is_household_member(household_id)); create policy "members insert own transactions" on public.transactions for insert with check(public.is_household_member(household_id) and user_id=auth.uid()); create policy "owners update transactions" on public.transactions for update using(user_id=auth.uid() and public.is_household_member(household_id)) with check(user_id=auth.uid() and public.is_household_member(household_id));
create policy "members manage recurring" on public.recurring_transactions for all using(public.is_household_member(household_id)) with check(public.is_household_member(household_id)); create policy "members manage budgets" on public.budgets for all using(public.is_household_member(household_id)) with check(public.is_household_member(household_id)); create policy "members manage goals" on public.goals for all using(public.is_household_member(household_id)) with check(public.is_household_member(household_id)); create policy "members manage debts" on public.debts for all using(public.is_household_member(household_id)) with check(public.is_household_member(household_id));
grant execute on function public.create_household(text,text), public.join_household(text) to authenticated;
